import { randomUUID } from "node:crypto";
import { appendFileSync, existsSync, mkdirSync, readFileSync, statSync, } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { sanitizeFilename, writeFileBestEffort } from "./bestEffortFs.js";
export const DEFAULT_REPLAYS_DIR = ".bitfab/replays";
export function resolveReplayArtifacts(input) {
    // Per-run directory so nothing is overwritten; per-path flags override, else
    // everything defaults inside this run's dir.
    const runId = makeRunId();
    const resolvedRunDir = resolve(input.runDir ?? join(DEFAULT_REPLAYS_DIR, runId));
    return {
        runId,
        runDir: resolvedRunDir,
        logPath: resolve(input.logPath ?? join(resolvedRunDir, "progress.log")),
        eventsLogPath: resolve(input.eventsLogPath ?? join(resolvedRunDir, "events.jsonl")),
        itemsDir: resolve(input.itemsDir ?? join(resolvedRunDir, "items")),
        resultPath: resolve(input.out ?? join(resolvedRunDir, "result.json")),
        replaysRoot: dirname(resolvedRunDir),
    };
}
function makeRunId() {
    const timestamp = new Date().toISOString().replace(/[^0-9A-Za-z]/g, "");
    return `${timestamp}-${process.pid}-${randomUUID().slice(0, 8)}`;
}
export function writeRunMetadata(artifacts, metadata) {
    // Best-effort metadata must never block the replay.
    writeFileBestEffort(join(artifacts.runDir, "run.json"), `${JSON.stringify({
        runId: artifacts.runId,
        label: metadata.label ?? null,
        status: metadata.status,
        testRunId: metadata.testRunId ?? null,
        resultCaptured: metadata.resultCaptured ?? null,
        startedAt: new Date(metadata.startedAt).toISOString(),
        finishedAt: metadata.finishedAt
            ? new Date(metadata.finishedAt).toISOString()
            : null,
        eventsLogPath: artifacts.eventsLogPath,
        itemsDir: artifacts.itemsDir,
        logPath: artifacts.logPath,
        resultPath: artifacts.resultPath,
    }, null, 2)}\n`);
}
export function writeTestRunPointer(artifacts, testRunId) {
    const dir = join(artifacts.replaysRoot, "by-test-run", sanitizeFilename(testRunId));
    // Best-effort lookup metadata; the run directory itself is authoritative.
    writeFileBestEffort(join(dir, "run.json"), `${JSON.stringify({
        testRunId,
        runId: artifacts.runId,
        runDir: artifacts.runDir,
        eventsLogPath: artifacts.eventsLogPath,
        itemsDir: artifacts.itemsDir,
        logPath: artifacts.logPath,
        resultPath: artifacts.resultPath,
    }, null, 2)}\n`);
}
export function extractTestRunId(result) {
    if (!result || typeof result !== "object") {
        return null;
    }
    const rec = result;
    if (typeof rec.testRunId === "string") {
        return rec.testRunId;
    }
    if (typeof rec.test_run_id === "string") {
        return rec.test_run_id;
    }
    return null;
}
export function ensureReplayArtifactsExcluded(startDir) {
    const gitDir = findGitDir(startDir);
    if (!gitDir) {
        return;
    }
    const excludePath = join(gitDir, "info", "exclude");
    try {
        const existing = existsSync(excludePath)
            ? readFileSync(excludePath, "utf8")
            : "";
        const patterns = [".bitfab/replays/", "scripts/replay-result.json"];
        const missing = patterns.filter((pattern) => !existing.includes(pattern));
        if (missing.length === 0) {
            return;
        }
        mkdirSync(dirname(excludePath), { recursive: true });
        appendFileSync(excludePath, `${existing.endsWith("\n") || existing.length === 0 ? "" : "\n"}# Bitfab replay runtime artifacts\n${missing.join("\n")}\n`);
    }
    catch {
        // Best-effort: ignore metadata should never block a replay.
    }
}
function findGitDir(startDir) {
    let current = resolve(startDir);
    while (true) {
        const candidate = join(current, ".git");
        try {
            if (existsSync(candidate)) {
                const stat = statSync(candidate);
                if (stat.isDirectory()) {
                    return candidate;
                }
                const contents = readFileSync(candidate, "utf8");
                const match = /^gitdir:\s*(.+)$/m.exec(contents);
                if (match?.[1]) {
                    return resolve(current, match[1].trim());
                }
            }
        }
        catch {
            return null;
        }
        const parent = dirname(current);
        if (parent === current) {
            return null;
        }
        current = parent;
    }
}
